import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();

        int[][] mat = new int[n][n];
        int zeroRow = -1;
        int zeroCol = -1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = scanner.nextInt();
                if (mat[i][j] == 0) {
                    zeroRow = i;
                    zeroCol = j;
                }
            }
        }

        // Escolhe uma linha que não contenha o zero para obter a soma mágica
        int targetRow = (zeroRow == 0) ? 1 : 0;
        int magicSum = 0;
        for (int j = 0; j < n; j++) {
            magicSum += mat[targetRow][j];
        }

        // Soma os elementos da linha com zero
        int currentSum = 0;
        for (int j = 0; j < n; j++) {
            currentSum += mat[zeroRow][j];
        }

        int missingValue = magicSum - currentSum;

        System.out.println(missingValue);
        System.out.println(zeroRow + 1);
        System.out.println(zeroCol + 1);

        scanner.close();
    }
}
